42	const PROCESSING_FEE = 5;
43	
44	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
45	  sword: 100,
46	  staff: 80,
47	  amulet: 60,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	};
52	
53	const FIRST_INSURANCE_PERCENT = 10;
54	
55	// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
56	// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
57	// is 110.00000000000001 in binary floating point. Since the final amount feeds
58	// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
59	const addPercent = (amount: number, percent: number): number =>
60	  amount + (amount * percent) / 100;
61	
62	const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
63	
64	const BLOCK_SIZE = 3;
65	const BLOCK_BASE_PREMIUM = 60;
66	const BLOCK_TYPE = "rune";
67	
68	const sumItemBasePremiums = (items: Item[]): number =>
69	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
70	
71	const formsBlock = (items: Item[]): boolean =>
72	  items.length === BLOCK_SIZE && items.every((item) => item.type === BLOCK_TYPE);
73	
74	const policyBasePremium = (items: Item[]): number =>
75	  formsBlock(items) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(items);
76	
77	const quotePremium = (step: QuoteStep): number =>
78	  Math.ceil(
79	    addPercent(policyBasePremium(step.items), FIRST_INSURANCE_PERCENT) +
80	      PROCESSING_FEE,
81	  );
82	
83	const runStep = (step: Step): StepResult => {
84	  if (step.op === "quote") return { premium: quotePremium(step) };
85	  throw new Error(`Unsupported step: ${step.op}`);
86	};
87	
88	export const runScenario = (scenario: Scenario): ScenarioResult => ({
89	  results: scenario.steps.map(runStep),
90	});
