const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const sumItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemBasePremium(item), 0);

const allSameType = (items: Item[]): boolean =>
  items.every((item) => item.type === items[0].type);

const formsBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE && allSameType(items);
